<script setup lang="ts">
type Regime='current'|'ccdii'|'ledger'
type Tx={id:number;at:string;label:string;amount:number;outcome:'pending'|'delivered'|'disputed'|'fraud';outcomeAt:string;dueAt:string;paidAt:string}
type GovernanceKey='annualProfit'|'externalHarm'|'baseHarmChance'|'bonus'|'longTermPay'|'clawback'|'annualPay'|'stakeYears'|'detection'|'attribution'|'enforcement'|'culpability'|'reportProtection'|'provision'|'horizon'
const props=withDefaults(defineProps<{locale?:'nl'|'en';mode?:'both'|'transaction'|'governance'}>(),{locale:'nl',mode:'both'})
const nl=computed(()=>props.locale==='nl')
const tx=reactive({balance:900,capacity:1200,committed:550,personalLimit:750})
const transactions=ref<Tx[]>([
 {id:1,at:'2026-09-17T09:10',label:'Webshop',amount:180,outcome:'delivered',outcomeAt:'2026-09-19T14:20',dueAt:'2026-09-30T23:59',paidAt:'2026-09-19T16:00'},
 {id:2,at:'2026-09-17T12:35',label:'Fietsreparatie',amount:320,outcome:'delivered',outcomeAt:'2026-09-17T17:10',dueAt:'2026-09-18T09:00',paidAt:'2026-10-05T09:00'},
 {id:3,at:'2026-09-17T12:36',label:'Laptop',amount:950,outcome:'fraud',outcomeAt:'2026-09-20T11:30',dueAt:'2026-10-01T23:59',paidAt:'2026-09-24T15:00'},
 {id:4,at:'2026-09-18T08:20',label:'Boodschappen',amount:85,outcome:'delivered',outcomeAt:'2026-09-18T08:55',dueAt:'2026-09-30T23:59',paidAt:''}
])
let nextId=5
const day=86400000
const editingIds=ref<number[]>([])
const money=(v:number)=>new Intl.NumberFormat(nl.value?'nl-NL':'en-GB',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v)
const moneyPrecise=(v:number)=>new Intl.NumberFormat(nl.value?'nl-NL':'en-GB',{style:'currency',currency:'EUR',minimumFractionDigits:1,maximumFractionDigits:1}).format(v)
const dateLabel=(value:string)=>value?new Date(value).toLocaleString(nl.value?'nl-NL':'en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):(nl.value?'niet ingesteld':'not set')
const outcomeLabel=(item:Tx)=>({pending:nl.value?'Onderweg':'Pending',delivered:nl.value?'Geleverd':'Delivered',disputed:nl.value?'Betwist':'Disputed',fraud:nl.value?'Niet geleverd / mogelijke fraude':'Not delivered / possible fraud'})[item.outcome]
const collectionCost=(amount:number)=>Math.max(40,Math.round((Math.min(amount,2500)*.15+Math.min(Math.max(amount-2500,0),2500)*.10+Math.min(Math.max(amount-5000,0),5000)*.05+Math.min(Math.max(amount-10000,0),190000)*.01+Math.max(amount-200000,0)*.005)*100)/100)
const feeAt=(item:Tx)=>item.dueAt?new Date(item.dueAt).getTime()+14*day:Infinity
const lateCost=(amount:number,item:Tx,t=Infinity)=>{if(!amount||item.outcome!=='delivered'||!item.dueAt||t<feeAt(item))return 0;const paid=item.paidAt?new Date(item.paidAt).getTime():Infinity;return paid<=feeAt(item)?0:collectionCost(amount)}
const paymentLabel=(item:Tx)=>{if(item.outcome!=='delivered')return outcomeLabel(item);if(!item.dueAt)return nl.value?'Geen vervaldatum':'No due date';if(!item.paidAt)return nl.value?'Nog niet betaald':'Not yet paid';const paid=new Date(item.paidAt).getTime(),due=new Date(item.dueAt).getTime();if(paid<=due)return nl.value?'Op tijd betaald':'Paid on time';if(paid<=feeAt(item))return nl.value?'Te laat, binnen hersteltermijn':'Late, within cure period';return nl.value?'Na hersteltermijn betaald':'Paid after cure period'}
const isEditing=(id:number)=>editingIds.value.includes(id)
const toggleEditing=(id:number)=>{editingIds.value=isEditing(id)?[]:[id]}
const simulate=(selected:Regime)=>{
 let own=Math.max(0,tx.balance),credit=Math.max(0,Math.min(tx.capacity-tx.committed,tx.personalLimit))
 const ownReleases:{at:number;amount:number}[]=[],creditReleases:{at:number;amount:number}[]=[]
 const releasedOwn=new Set<number>(),releasedCredit=new Set<number>()
 return [...transactions.value].sort((a,b)=>a.at.localeCompare(b.at)||a.id-b.id).map(item=>{
  const at=new Date(item.at).getTime()
  ownReleases.forEach((release,index)=>{if(!releasedOwn.has(index)&&release.at<=at){own+=release.amount;releasedOwn.add(index)}})
  creditReleases.forEach((release,index)=>{if(!releasedCredit.has(index)&&release.at<=at){credit+=release.amount;releasedCredit.add(index)}})
  const ownBefore=own,creditBefore=credit
  const ownNeeded=selected==='ledger'?Math.min(item.amount,own):0
  const creditNeeded=selected==='ledger'?Math.max(0,item.amount-ownNeeded):item.amount
  const accepted=selected==='current'||creditNeeded<=credit
  if(accepted){
   if(selected==='ledger')own-=ownNeeded
   if(selected!=='current')credit-=creditNeeded
   const closesAt=item.paidAt?new Date(item.paidAt).getTime():NaN
   if(Number.isFinite(closesAt)){
    if(selected==='ledger'&&item.outcome!=='delivered'&&ownNeeded)ownReleases.push({at:closesAt,amount:ownNeeded})
    if(selected!=='current'&&creditNeeded)creditReleases.push({at:closesAt,amount:creditNeeded})
   }
  }
  return{...item,ownNeeded,creditNeeded,accepted,ownBefore,creditBefore,ownAfter:own,creditAfter:credit}
 })
}
const comparison=computed(()=>{const current=simulate('current'),ccdii=simulate('ccdii'),ledger=simulate('ledger');return current.map((item,index)=>({item,current:item,ccdii:ccdii[index],ledger:ledger[index],currentCost:lateCost(item.amount,item),ccdiiCost:ccdii[index].accepted?lateCost(item.amount,item):0,ledgerCost:ledger[index].accepted?lateCost(ledger[index].creditNeeded,item):0}))})
const addTransaction=()=>{const last=[...transactions.value].sort((a,b)=>a.at.localeCompare(b.at)).at(-1);const d=new Date(last?.at||'2026-09-17T09:00');d.setMinutes(d.getMinutes()+45);const delivery=new Date(d);delivery.setDate(delivery.getDate()+2);const due=new Date(delivery);due.setDate(due.getDate()+14);const paid=new Date(delivery);paid.setDate(paid.getDate()+1);const id=nextId++;transactions.value.push({id,at:d.toISOString().slice(0,16),label:nl.value?'Nieuwe aankoop':'New purchase',amount:250,outcome:'delivered',outcomeAt:delivery.toISOString().slice(0,16),dueAt:due.toISOString().slice(0,16),paidAt:paid.toISOString().slice(0,16)});editingIds.value=[id]}
const removeTransaction=(id:number)=>{transactions.value=transactions.value.filter(x=>x.id!==id);editingIds.value=editingIds.value.filter(x=>x!==id)}
const animationRegime=ref<Regime>('ledger')
const animationTxId=ref(3)
const animationStep=ref(0)
const animationPlaying=ref(false)
const animationSection=ref<HTMLElement|null>(null)
let animationTimer:ReturnType<typeof setInterval>|undefined
const animationItem=computed(()=>transactions.value.find(x=>x.id===animationTxId.value)||transactions.value[0])
const animationResult=computed(()=>simulate(animationRegime.value).find(x=>x.id===animationItem.value?.id))
const animationSteps=computed(()=>{
 const item=animationItem.value,result=animationResult.value
 if(!item||!result)return[]
 const rejected=!result.accepted
 const names=nl.value
  ?['Beginsituatie','Bestelling geplaatst',rejected?'Controle: geweigerd':'Controle: geaccepteerd','Winkel maakt gereed',item.outcome==='delivered'?'Levering aanvaard':item.outcome==='pending'?'Goederen onderweg':'Levering betwist of uitgebleven',item.outcome==='delivered'?(item.paidAt?'Betaald':'Schuld blijft open'):item.paidAt?'Reservering vrijgegeven':'In afwachting van oplossing']
  :['Initial situation','Order placed',rejected?'Check: rejected':'Check: accepted','Merchant prepares order',item.outcome==='delivered'?'Delivery accepted':item.outcome==='pending'?'Goods in transit':'Delivery disputed or absent',item.outcome==='delivered'?(item.paidAt?'Paid':'Debt remains open'):item.paidAt?'Reservation released':'Awaiting resolution']
 return names.map((name,index)=>({name,index}))
})
const animationState=computed(()=>{
 const item=animationItem.value,result=animationResult.value,step=animationStep.value
 if(!item||!result)return null
 const rejected=!result.accepted
 const active=step>=2&&!rejected
 const delivered=active&&item.outcome==='delivered'&&step>=4
 const paid=delivered&&!!item.paidAt&&step>=5
 const refunded=active&&item.outcome!=='delivered'&&!!item.paidAt&&step>=5
 const creditBase=animationRegime.value==='ledger'?result.creditNeeded:item.amount
 const collectionCosts=delivered?lateCost(creditBase,item):0
 const ownReserved=animationRegime.value==='ledger'&&active&&!delivered&&!refunded?result.ownNeeded:0
 const creditReserved=animationRegime.value==='ledger'&&active&&!delivered&&!refunded?result.creditNeeded:0
 const debt=active&&!paid&&((animationRegime.value!=='ledger'&&step>=2)||(animationRegime.value==='ledger'&&delivered))?creditBase+(step>=4?collectionCosts:0):0
 const freeOwn=animationRegime.value==='ledger'?(refunded||!active?result.ownBefore:result.ownAfter):result.ownBefore
 const sharedCreditBefore=animationRegime.value==='current'?null:result.creditBefore
 const creditAvailable=sharedCreditBefore===null?null:(!active||paid||refunded?sharedCreditBefore:Math.max(0,result.creditAfter-(delivered&&step>=4?collectionCosts:0)))
 const merchantPaid=active&&((animationRegime.value==='ledger'&&delivered)||(animationRegime.value!=='ledger'&&step>=3))
 const moneyAt=rejected||step<2||refunded?'customer':animationRegime.value==='ledger'&&!delivered?'provider':merchantPaid?'merchant':'provider'
 const goodsAt=step<3||rejected?'merchant':step===3?'transit':item.outcome==='delivered'?'customer':item.outcome==='pending'?'transit':'missing'
 const action=rejected&&step>=2?(nl.value?'Transactie stopt: onvoldoende toegestane kredietruimte.':'Transaction stops: insufficient permitted credit capacity.')
  :step===0?(nl.value?'Geld en goederen bevinden zich nog bij hun oorspronkelijke eigenaar.':'Money and goods remain with their original owner.')
  :step===1?(nl.value?'De klant vraagt de aankoop aan; er is nog niets definitief overgemaakt.':'The customer requests the purchase; nothing has been transferred definitively yet.')
  :step===2?(animationRegime.value==='ledger'?(nl.value?'Eigen geld en alleen het eventuele tekort aan krediet worden gereserveerd.':'Own funds and only any credit shortfall are reserved.'):(nl.value?'Het volledige bedrag wordt als kredietverplichting beoordeeld.':'The full amount is assessed as a credit obligation.'))
  :step===3?(nl.value?'De winkel heeft een geaccepteerde bestelling en verzendt de goederen.':'The merchant has an accepted order and dispatches the goods.')
  :step===4?(item.outcome==='delivered'?(nl.value?'De levering is aanvaard; nu kan definitieve afrekening plaatsvinden.':'Delivery is accepted; final settlement can now occur.'):(nl.value?'Zonder aanvaarde levering blijft de reservering geblokkeerd en wordt niet definitief afgerekend.':'Without accepted delivery, the reservation remains blocked and is not settled definitively.'))
  :item.outcome==='delivered'?(paid?(collectionCosts?(nl.value?`De klant betaalt na de hersteltermijn: ${money(creditBase)} plus ${money(collectionCosts)} incassokosten. Het aankoopbedrag blijft bij de winkel.`:`The customer pays after the cure period: ${money(creditBase)} plus ${money(collectionCosts)} collection costs. The purchase amount remains with the merchant.`):(nl.value?'De betaling is voltooid. Het aankoopbedrag blijft bij de winkel en de schuld bij de klant verdwijnt.':'Payment is complete. The purchase amount remains with the merchant and the customer debt disappears.')):(nl.value?`De winkel ontvangt ${money(item.amount)} via de betaal-/kredietlaag. De klant houdt ${money(debt)} schuld; die ruimte komt pas na echte betaling terug.`:`The merchant receives ${money(item.amount)} through the payment/credit layer. The customer retains ${money(debt)} debt; that capacity returns only after actual payment.`))
  :refunded?(nl.value?'De kwestie is opgelost en eigen geld en kredietreservering worden aan de klant vrijgegeven.':'The issue is resolved and own funds and the credit reservation are released to the customer.'):(nl.value?'Geld en kredietruimte blijven beschermd maar tijdelijk niet beschikbaar tot de kwestie is opgelost.':'Funds and credit capacity remain protected but temporarily unavailable until the issue is resolved.')
 return{rejected,active,delivered,paid,refunded,ownReserved,creditReserved,creditAvailable,debt,freeOwn,merchantPaid,collectionCosts:paid?collectionCosts:0,moneyAt,goodsAt,action}
})
const stopAnimation=()=>{animationPlaying.value=false;if(animationTimer)clearInterval(animationTimer);animationTimer=undefined}
const playAnimation=()=>{stopAnimation();animationStep.value=0;animationPlaying.value=true;animationTimer=setInterval(()=>{if(animationStep.value>=animationSteps.value.length-1){stopAnimation();return}animationStep.value++},1300)}
const setAnimationStep=(step:number)=>{stopAnimation();animationStep.value=Math.max(0,Math.min(step,animationSteps.value.length-1))}
const showInAnimation=async(id:number)=>{animationTxId.value=id;setAnimationStep(0);await nextTick();animationSection.value?.scrollIntoView({behavior:'smooth',block:'center'})}
watch([animationRegime,animationTxId],()=>setAnimationStep(0))
onBeforeUnmount(stopAnimation)
const chart=computed(()=>{const currentAll=simulate('current'),ccdiiAll=simulate('ccdii'),ledgerAll=simulate('ledger'),current=currentAll.filter(x=>x.accepted),ccdii=ccdiiAll.filter(x=>x.accepted),ledger=ledgerAll.filter(x=>x.accepted);const stamps=transactions.value.flatMap(x=>[x.at,x.outcomeAt,x.dueAt,x.dueAt?new Date(new Date(x.dueAt).getTime()+14*day).toISOString():'',x.paidAt]).filter(Boolean).map(x=>new Date(x).getTime()).filter(Number.isFinite);const start=stamps.length?Math.min(...stamps):Date.now(),end=(stamps.length?Math.max(...stamps,start+7*day):start+7*day)+2*day;const points=Array.from({length:15},(_,i)=>start+(end-start)*i/14);const openTraditional=(items:ReturnType<typeof simulate>,t:number)=>items.reduce((sum,x)=>{const buy=new Date(x.at).getTime(),close=x.paidAt?new Date(x.paidAt).getTime():Infinity;return sum+(t>=buy&&t<close?x.amount+lateCost(x.amount,x,t):0)},0);const openLedger=(t:number,kind:'reserve'|'credit')=>ledger.reduce((sum,x)=>{const buy=new Date(x.at).getTime(),out=x.outcomeAt?new Date(x.outcomeAt).getTime():Infinity,close=x.paidAt?new Date(x.paidAt).getTime():Infinity;if(kind==='reserve'){const release=x.outcome==='delivered'?out:close;return sum+(t>=buy&&t<release?x.ownNeeded:0)}const active=t>=buy&&t<close;return sum+(active?x.creditNeeded+(x.outcome==='delivered'&&t>=out?lateCost(x.creditNeeded,x,t):0):0)},0);const reserve=points.map(t=>openLedger(t,'reserve')),ledgerCredit=points.map(t=>openLedger(t,'credit'));const series={current:points.map(t=>openTraditional(current,t)),ccdii:points.map(t=>openTraditional(ccdii,t)),reserve,ledgerCredit,ledgerTotal:reserve.map((v,i)=>v+ledgerCredit[i])};const max=Math.max(1,...series.current,...series.ccdii,...series.reserve,...series.ledgerCredit,...series.ledgerTotal);const line=(values:number[])=>values.map((v,i)=>`${28+i*34},${155-v/max*120}`).join(' ');const rejected=(items:ReturnType<typeof simulate>)=>({count:items.filter(x=>!x.accepted).length,amount:items.filter(x=>!x.accepted).reduce((sum,x)=>sum+x.amount,0)});return{points,series,max,line,rejected:{current:rejected(currentAll),ccdii:rejected(ccdiiAll),ledger:rejected(ledgerAll)},first:new Date(start).toLocaleDateString(nl.value?'nl-NL':'en-GB',{day:'numeric',month:'short'}),last:new Date(end).toLocaleDateString(nl.value?'nl-NL':'en-GB',{day:'numeric',month:'short'})}})
const governance=reactive({annualProfit:20,externalHarm:60,baseHarmChance:35,bonus:55,longTermPay:25,clawback:30,annualPay:1.2,stakeYears:1,detection:45,attribution:50,enforcement:55,culpability:2,reportProtection:35,provision:30,horizon:5})
const activeGovernance=ref<GovernanceKey>('bonus')
const governanceHelp=computed(()=>({
 annualProfit:{title:nl.value?'Jaarwinst':'Annual profit',text:nl.value?'Vergroot de winst waarop directe en uitgestelde beloning worden berekend. De maatschappelijke schade verandert hierdoor niet automatisch.':'Increases the profit on which immediate and deferred compensation are calculated. Societal harm does not automatically change with it.'},
 externalHarm:{title:nl.value?'Schade als het misgaat':'Harm if it occurs',text:nl.value?'De omvang van één schadelijk scenario. De verwachte schade ontstaat pas na vermenigvuldiging met de berekende kans dat het scenario werkelijk optreedt.':'The magnitude of one harmful scenario. Expected harm follows only after multiplication by the calculated probability that it actually occurs.'},
 baseHarmChance:{title:nl.value?'Basiskans op langetermijnschade':'Baseline probability of long-term harm',text:nl.value?'De kans vóór governance-effecten. Dit is een scenario-aanname, geen gemeten kans. Preventieve prikkels kunnen haar in het model verlagen, maar nooit tot nul.':'The probability before governance effects. This is a scenario assumption, not a measured probability. Preventive incentives can reduce it in the model, but never to zero.'},
 bonus:{title:nl.value?'Directe bonusdruk':'Immediate bonus pressure',text:nl.value?'Een hogere waarde brengt meer beloning naar het heden. Dat vergroot de prikkel om resultaten te boeken voordat latere gevolgen zichtbaar zijn.':'A higher value moves more reward into the present, strengthening incentives to produce results before later consequences appear.'},
 longTermPay:{title:nl.value?'Uitgestelde beloning':'Deferred compensation',text:nl.value?'Een groter deel van de beloning blijft langer verbonden aan latere resultaten en gevolgen.':'A larger share of compensation remains connected to later results and consequences.'},
 clawback:{title:'Clawback',text:nl.value?'Geeft aan hoeveel reeds toegekende beloning kan worden teruggevorderd wanneer later schade of verkeerd handelen blijkt.':'Indicates how much awarded compensation can be recovered when harm or misconduct emerges later.'},
 annualPay:{title:nl.value?'Jaarbeloning beslisser':'Decision-maker annual compensation',text:nl.value?'Maakt het bedrag dat persoonlijk op het spel staat concreet. Het is een scenario-invoer, geen aanname dat iedere beslisser dit bedrag verdient.':'Makes the amount personally at risk concrete. It is a scenario input, not an assumption that every decision-maker earns this amount.'},
 stakeYears:{title:nl.value?'Persoonlijk bedrag op het spel':'Personal amount at risk',text:nl.value?'Het maximale persoonlijke gevolg, uitgedrukt in jaren beloning. Nul betekent geen financieel verhaal; vijf betekent maximaal vijf jaar beloning, niet onbeperkte of strafrechtelijke bestraffing.':'The maximum personal consequence expressed in years of compensation. Zero means no financial recourse; five means up to five years of compensation, not unlimited or criminal punishment.'},
 detection:{title:nl.value?'Kans op onafhankelijke ontdekking':'Chance of independent detection',text:nl.value?'De kans dat toezicht, accountants, journalistiek of benadeelden ontstane schade ontdekken wanneer interne melding uitblijft.':'The chance that regulators, auditors, journalism or affected parties discover harm when internal reporting fails.'},
 attribution:{title:nl.value?'Kans op toeschrijving':'Chance of attribution',text:nl.value?'De kans dat gevonden schade aan een concreet besluit en de verantwoordelijke beslissers kan worden gekoppeld.':'The chance that detected harm can be linked to a specific decision and the responsible decision-makers.'},
 enforcement:{title:nl.value?'Kans op daadwerkelijke handhaving':'Chance of actual enforcement',text:nl.value?'De kans dat aantoonbaar verwijtbaar handelen werkelijk tot terugvordering, aansprakelijkheid of een andere passende consequentie leidt.':'The chance that demonstrably culpable conduct actually results in clawback, liability or another appropriate consequence.'},
 culpability:{title:nl.value?'Verwijtbaarheid van het scenario':'Culpability in this scenario',text:nl.value?'Onderscheidt een gewone tegenvaller van nalatigheid, grove nalatigheid en opzet. Zwaardere persoonlijke gevolgen horen pas bij grotere verwijtbaarheid.':'Distinguishes an ordinary adverse outcome from negligence, gross negligence and intent. Stronger personal consequences should require greater culpability.'},
 reportProtection:{title:nl.value?'Bescherming en ruimte om te melden':'Protection and scope to report',text:nl.value?'Maakt het waarschijnlijker dat medewerkers risico’s en schade intern melden. Dit helpt eerder ingrijpen en verkleint de kans dat bekende schade ongemeld blijft.':'Makes it more likely that staff report risks and harm internally. This supports earlier intervention and reduces the probability that known harm remains unreported.'},
 provision:{title:nl.value?'Voorziening voor schade':'Provision for harm',text:nl.value?'Reserveert vooraf een groter deel van de verwachte schade. Dit vermindert de ongedekte schade, niet de schade zelf.':'Sets aside a larger share of expected harm in advance. This reduces uncovered harm, not the harm itself.'},
 horizon:{title:nl.value?'Moment waarop gevolgen blijken':'When consequences emerge',text:nl.value?'Verplaatst het moment waarop schade zichtbaar wordt. Een langere termijn maakt kortlopende beloning en verantwoordelijkheid makkelijker van elkaar los te koppelen.':'Moves the point at which harm becomes visible. A longer horizon makes it easier for short-term reward and accountability to become detached.'}
})[activeGovernance.value])
const clamp=(v:number,min=0,max=1)=>Math.max(min,Math.min(max,v))
const pct=(v:number)=>Math.round(v*100)
const culpabilityLabel=computed(()=>[(nl.value?'Geen verwijt':'No fault'),(nl.value?'Nalatigheid':'Negligence'),(nl.value?'Grove nalatigheid':'Gross negligence'),(nl.value?'Opzet':'Intent')][governance.culpability])
const governanceRisk=computed(()=>{
 const g=governance
 const horizonPenalty=clamp((g.horizon-1)/14)
 const internalReport=clamp(.12+.52*g.reportProtection/100+.10*g.longTermPay/100-.20*g.bonus/100-.10*horizonPenalty,.03,.95)
 const externalDetection=clamp(g.detection/100*(1-.18*horizonPenalty),.01,.99)
 const unreported=clamp((1-internalReport)*(1-externalDetection))
 const discovered=1-unreported
 const attribution=clamp(g.attribution/100*(1-.25*horizonPenalty),.01,.99)
 const culpabilityFactor=[0,.35,.72,1][g.culpability]
 const accountability=clamp(discovered*attribution*g.enforcement/100*culpabilityFactor)
 const delayedReward=g.annualProfit*g.longTermPay/100
 const amountAtRisk=g.annualPay*g.stakeYears+delayedReward*g.clawback/100
 const sanctionWeight=clamp(amountAtRisk/Math.max(.1,g.annualPay*3))
 const deterrenceSignal=clamp(accountability*sanctionWeight)
 const governancePrevention=clamp(.18*g.longTermPay/100+.12*g.reportProtection/100-.18*g.bonus/100)
 const base=g.baseHarmChance/100
 const harmChanceLow=clamp(base*(1-governancePrevention-.15*deterrenceSignal),.005,.95)
 const harmChance=clamp(base*(1-governancePrevention-.35*deterrenceSignal),.005,.95)
 const harmChanceHigh=clamp(base*(1-governancePrevention-.60*deterrenceSignal),.005,.95)
 const expectedHarm=g.externalHarm*harmChance
 const uncoveredHarm=expectedHarm*(1-g.provision/100)
 const coveredHarm=expectedHarm*g.provision/100
 const shortReward=g.annualProfit*g.bonus/100
 const personalExposure=accountability*amountAtRisk
 const alignment=clamp(.40*(1-harmChance)+.25*(1-unreported)+.20*accountability+.15*g.provision/100)
 return{harmChance,harmChanceLow,harmChanceHigh,internalReport,externalDetection,unreported,attribution,accountability,amountAtRisk,expectedHarm,uncoveredHarm,coveredHarm,shortReward,delayedReward,personalExposure,alignment}
})
const shortReward=computed(()=>Math.round(governanceRisk.value.shortReward*10)/10)
const delayedReward=computed(()=>Math.round(governanceRisk.value.delayedReward*10)/10)
</script>

<template>
 <section class="risk-model" data-analytics-model="risk-responsibility">
  <header><p>{{props.mode==='both'?(nl?'TWEE SCHALEN':'TWO SCALES'):(nl?'SCENARIOVERKENNER':'SCENARIO EXPLORER')}}</p><h3>{{props.mode==='transaction'?(nl?'Veilig reserveren door de tijd':'Safe reservation over time'):props.mode==='governance'?(nl?'Beloning en gevolgen door de tijd':'Reward and consequences over time'):(nl?'Financiële veiligheid én bestuurlijke afstemming':'Financial safety and governance alignment')}}</h3><span>{{nl?'De verkenner gebruikt didactische aannames. Zij toont relaties, geen kredietbesluit of moreel eindoordeel.':'The explorer uses teaching assumptions. It shows relationships, not a credit decision or final moral verdict.'}}</span></header>
  <section v-if="props.mode!=='governance'" class="model-section">
   <div class="section-head"><b>1</b><div><h4>{{nl?'Persoonlijke financiële veiligheid':'Personal financial safety'}}</h4><p>{{nl?'Voeg transacties toe en zie in tijdsvolgorde wanneer eigen geld wordt gereserveerd, krediet nodig wordt en een grens de aankoop weigert.':'Add transactions and see, in time order, when owned funds are reserved, credit becomes necessary and a limit rejects a purchase.'}}</p></div></div>
   <div class="transaction-layout">
    <div class="controls compact">
     <label><span>{{nl?'Eigen vrij geld':'Own available funds'}} <output>{{money(tx.balance)}}</output></span><input v-model.number="tx.balance" type="range" min="0" max="3000" step="50"></label>
     <label><span>{{nl?'Maximale kredietcapaciteit':'Maximum credit capacity'}} <output>{{money(tx.capacity)}}</output></span><input v-model.number="tx.capacity" type="range" min="0" max="3000" step="50"></label>
     <label><span>{{nl?'Al gecommitteerd':'Already committed'}} <output>{{money(tx.committed)}}</output></span><input v-model.number="tx.committed" type="range" min="0" :max="tx.capacity" step="50"></label>
     <label><span>{{nl?'Persoonlijke kredietgrens':'Personal credit limit'}} <output>{{money(tx.personalLimit)}}</output></span><input v-model.number="tx.personalLimit" type="range" min="0" max="2000" step="50"></label>
    </div>
    <div class="transaction-editor">
     <div class="editor-head"><strong>{{nl?'Transacties':'Transactions'}}</strong><button @click="addTransaction">＋ {{nl?'Toevoegen':'Add'}}</button></div>
     <article v-for="item in transactions" :key="item.id" class="tx-card" :class="{editing:isEditing(item.id)}">
      <div class="tx-read"><div><strong>{{item.label}}</strong><span>{{money(item.amount)}} · {{outcomeLabel(item)}}</span></div><div><span>{{dateLabel(item.at)}}</span><small>{{paymentLabel(item)}}<template v-if="lateCost(item.amount,item)"> · +{{money(lateCost(item.amount,item))}} {{nl?'incassokosten':'collection costs'}}</template></small></div><div class="tx-actions"><button @click="showInAnimation(item.id)">▶ {{nl?'Bekijk':'View'}}</button><button :aria-expanded="isEditing(item.id)" @click="toggleEditing(item.id)">{{isEditing(item.id)?(nl?'Sluiten':'Close'):(nl?'Bewerken':'Edit')}}</button></div></div>
      <div v-if="isEditing(item.id)" class="tx-edit">
       <label><span>{{nl?'Besteld':'Ordered'}}</span><input v-model="item.at" type="datetime-local"></label>
       <label><span>{{nl?'Omschrijving':'Description'}}</span><input v-model="item.label"></label>
       <label><span>{{nl?'Bedrag':'Amount'}}</span><i>€ <input v-model.number="item.amount" type="number" min="0" step="5"></i></label>
       <label><span>{{nl?'Afleverstatus':'Delivery status'}}</span><select v-model="item.outcome"><option value="pending">{{nl?'Onderweg':'Pending'}}</option><option value="delivered">{{nl?'Geleverd':'Delivered'}}</option><option value="disputed">{{nl?'Betwist':'Disputed'}}</option><option value="fraud">{{nl?'Niet geleverd / mogelijke fraude':'Not delivered / possible fraud'}}</option></select></label>
       <label><span>{{nl?'Levering / melding':'Delivery / report'}}</span><input v-model="item.outcomeAt" type="datetime-local" :disabled="item.outcome==='pending'"></label>
       <label><span>{{nl?'Vervaldatum':'Due date'}}</span><input v-model="item.dueAt" type="datetime-local" :disabled="item.outcome!=='delivered'"></label>
       <label><span>{{item.outcome==='delivered'?(nl?'Betaald':'Paid'):(nl?'Opgelost / terugbetaald':'Resolved / refunded')}}</span><input v-model="item.paidAt" type="datetime-local" :disabled="item.outcome==='pending'"></label>
       <button class="remove" @click="removeTransaction(item.id)">{{nl?'Verwijderen':'Remove'}}</button>
      </div>
     </article>
    </div>
   </div>
   <div class="scenario-comparison">
    <div class="scenario-head"><strong>{{nl?'Gevolg per transactie':'Result per transaction'}}</strong><span>{{nl?'Huidig':'Current'}}</span><span>{{nl?'CCDII-voorstel':'CCDII bill'}}</span><span>{{nl?'Reserveringsmodel':'Reservation model'}}</span></div>
    <article v-for="row in comparison" :key="row.item.id" role="button" tabindex="0" :aria-pressed="row.item.id===animationTxId" :class="{fraud:row.item.outcome==='fraud',selected:row.item.id===animationTxId}" @click="showInAnimation(row.item.id)" @keydown.enter.prevent="showInAnimation(row.item.id)" @keydown.space.prevent="showInAnimation(row.item.id)">
     <div><time>{{row.item.at.replace('T',' · ')}}</time><strong>{{row.item.label}} · {{money(row.item.amount)}}</strong><small v-if="row.item.outcome==='fraud'&&!row.item.paidAt">{{nl?'niet geleverd; terugbetaling onzeker zolang geen oplossing is ingevuld':'not delivered; refund uncertain while no resolution is entered'}}</small><small v-else-if="row.item.outcome==='fraud'">{{nl?'niet geleverd; reservering vrijgegeven op de oplossingsdatum':'not delivered; reservation released on the resolution date'}}</small></div>
     <p :data-label="nl?'HUIDIG':'CURRENT'">{{nl?'Aanbieder beslist afzonderlijk; volledige verplichting kan openblijven.':'Provider decides separately; the full obligation may remain open.'}}<strong v-if="row.currentCost">+{{money(row.currentCost)}} {{nl?'na hersteltermijn':'after cure period'}}</strong></p>
     <p :data-label="nl?'CCDII-VOORSTEL':'CCDII BILL'" :class="{rejected:!row.ccdii.accepted}">{{row.ccdii.accepted?(nl?'Volledig als krediet getoetst en geregistreerd.':'Assessed and recorded in full as credit.'):(nl?'Geweigerd door beschikbare kredietruimte.':'Rejected because of available credit capacity.')}}<strong v-if="row.ccdiiCost">+{{money(row.ccdiiCost)}} {{nl?'na hersteltermijn':'after cure period'}}</strong></p>
     <p :data-label="nl?'RESERVERINGSMODEL':'RESERVATION MODEL'" :class="{rejected:!row.ledger.accepted}"><template v-if="row.ledger.accepted">{{money(row.ledger.ownNeeded)}} {{nl?'eigen geld gereserveerd':'owned funds reserved'}}<template v-if="row.ledger.creditNeeded"> · {{money(row.ledger.creditNeeded)}} {{nl?'krediet':'credit'}}</template><template v-if="row.item.outcome==='fraud'"> · {{nl?'geen afrekening zonder aanvaarde levering':'no settlement without accepted delivery'}}</template><strong v-if="row.ledgerCost">+{{money(row.ledgerCost)}} {{nl?'alleen over kredietdeel':'on credit share only'}}</strong></template><template v-else>{{nl?'Geweigerd door beschikbare kredietruimte.':'Rejected because of available credit capacity.'}}</template></p>
    </article>
   </div>
   <section ref="animationSection" class="transaction-animation">
    <div class="animation-head"><div><strong>{{nl?'Van bestelling tot levering en betaling':'From order to delivery and payment'}}</strong><small>{{nl?'Volg waar geld, kredietruimte en goederen zich tijdens iedere stap bevinden.':'Follow where money, credit capacity and goods are located during each step.'}}</small></div><div class="animation-selectors"><select v-model="animationRegime" :aria-label="nl?'Scenario':'Scenario'"><option value="current">{{nl?'Huidige situatie':'Current situation'}}</option><option value="ccdii">CCDII</option><option value="ledger">{{nl?'Reserveringsmodel':'Reservation model'}}</option></select><select v-model.number="animationTxId" :aria-label="nl?'Transactie':'Transaction'"><option v-for="item in transactions" :key="item.id" :value="item.id">{{item.label}} · {{money(item.amount)}}</option></select></div></div>
    <div v-if="animationState&&animationItem" class="flow-stage" :class="[`money-${animationState.moneyAt}`,`goods-${animationState.goodsAt}`,{rejected:animationState.rejected}]">
     <article class="actor customer"><span>👤</span><b>{{nl?'Klant':'Customer'}}</b><dl><div><dt>{{nl?'Vrij geld':'Free funds'}}</dt><dd>{{money(animationState.freeOwn)}}</dd></div><div><dt>{{nl?'Gereserveerd eigen geld':'Reserved own funds'}}</dt><dd>{{money(animationState.ownReserved)}}</dd></div><div><dt>{{nl?'Beschikbare kredietruimte':'Available credit capacity'}}</dt><dd>{{animationState.creditAvailable===null?(nl?'niet centraal bewaakt':'not centrally tracked'):money(animationState.creditAvailable)}}</dd></div><div><dt>{{nl?'Schuld inclusief kosten':'Debt including costs'}}</dt><dd>{{money(animationState.debt)}}</dd></div></dl></article>
     <div class="flow-space"><div class="money-token"><span>€</span><small>{{money(animationItem.amount)}}</small></div><div class="goods-token"><span>▣</span><small>{{animationItem.label}}</small></div><div v-if="animationState.rejected&&animationStep>=2" class="stop-token">×</div></div>
     <article class="actor provider"><span>🏦</span><b>{{nl?'Betaal- en reserveringslaag':'Payment and reservation layer'}}</b><dl><div><dt>{{nl?'Eigen geld geblokkeerd':'Own funds blocked'}}</dt><dd>{{money(animationState.ownReserved)}}</dd></div><div><dt>{{nl?'Kredietruimte bezet':'Credit capacity occupied'}}</dt><dd>{{money(animationState.creditReserved)}}</dd></div><div><dt>{{nl?'Te innen schuld':'Debt receivable'}}</dt><dd>{{money(animationState.debt)}}</dd></div><div><dt>{{nl?'Betaalde incassokosten':'Collection costs paid'}}</dt><dd>{{money(animationState.collectionCosts)}}</dd></div></dl></article>
     <div class="flow-space second"></div>
     <article class="actor merchant"><span>🏪</span><b>{{nl?'Winkel':'Merchant'}}</b><dl><div><dt>{{nl?'Bestelling':'Order'}}</dt><dd>{{animationStep>=1&&!animationState.rejected?(nl?'ontvangen':'received'):'—'}}</dd></div><div><dt>{{nl?'Goederen':'Goods'}}</dt><dd>{{animationState.goodsAt==='merchant'?(nl?'op voorraad':'in stock'):animationState.goodsAt==='transit'?(nl?'onderweg':'in transit'):animationState.goodsAt==='customer'?(nl?'bij klant':'with customer'):(nl?'niet aangetroffen':'not located')}}</dd></div><div><dt>{{nl?'Betaling ontvangen':'Payment received'}}</dt><dd>{{animationState.merchantPaid?money(animationItem.amount):money(0)}}</dd></div></dl></article>
    </div>
    <div class="animation-status"><b>{{animationStep+1}}/{{animationSteps.length}} · {{animationSteps[animationStep]?.name}}</b><p>{{animationState?.action}}</p></div>
    <div class="animation-controls"><button @click="setAnimationStep(animationStep-1)" :disabled="animationStep===0">← {{nl?'Vorige':'Previous'}}</button><button @click="animationPlaying?stopAnimation():playAnimation()">{{animationPlaying?'■ '+(nl?'Stop':'Stop'):'▶ '+(nl?'Afspelen':'Play')}}</button><button @click="setAnimationStep(animationStep+1)" :disabled="animationStep>=animationSteps.length-1">{{nl?'Volgende':'Next'}} →</button></div>
    <div class="animation-steps"><button v-for="step in animationSteps" :key="step.index" :class="{active:step.index===animationStep}" :aria-label="step.name" @click="setAnimationStep(step.index)">{{step.index+1}}</button></div>
   </section>
   <div class="exposure-chart"><div><strong>{{nl?'Financiële ruimte, schuld en geweigerde transacties':'Financial capacity, debt and rejected transactions'}}</strong><small>{{nl?'De lijnen meten niet allemaal hetzelfde: gereserveerd eigen geld is tijdelijk niet beschikbaar, maar is geen schuld. De totaallijn van het reserveringsmodel telt geblokkeerd eigen geld en bezette kredietruimte bij elkaar op.':'The lines do not all measure the same thing: reserved own funds are temporarily unavailable, but are not debt. The reservation model total adds blocked own funds and occupied credit capacity.'}}</small></div>
    <div class="rejection-summary"><span><b>{{nl?'Huidig':'Current'}}</b>{{chart.rejected.current.count}} {{nl?'geweigerd':'rejected'}} · {{money(chart.rejected.current.amount)}}</span><span><b>CCDII</b>{{chart.rejected.ccdii.count}} {{nl?'geweigerd':'rejected'}} · {{money(chart.rejected.ccdii.amount)}}</span><span><b>{{nl?'Reserveringsmodel':'Reservation model'}}</b>{{chart.rejected.ledger.count}} {{nl?'geweigerd':'rejected'}} · {{money(chart.rejected.ledger.amount)}}</span></div>
    <svg viewBox="0 0 520 185" role="img" :aria-label="nl?'Financiële verplichtingen en bezette ruimte door de tijd':'Financial obligations and occupied capacity over time'"><line x1="28" y1="155" x2="504" y2="155"/><line x1="28" y1="35" x2="28" y2="155"/><polyline class="current-line" :points="chart.line(chart.series.current)"/><polyline class="ccdii-line" :points="chart.line(chart.series.ccdii)"/><polyline class="total-line" :points="chart.line(chart.series.ledgerTotal)"/><polyline class="reserve-line" :points="chart.line(chart.series.reserve)"/><polyline class="debt-line" :points="chart.line(chart.series.ledgerCredit)"/><text x="28" y="174">{{chart.first}}</text><text x="504" y="174" text-anchor="end">{{chart.last}}</text><text x="22" y="39" text-anchor="end">{{money(chart.max)}}</text></svg><div class="legend"><span><i class="current-key"></i>{{nl?'huidige schuld + kosten':'current debt + costs'}}</span><span><i class="ccdii-key"></i>CCDII {{nl?'schuld + kosten':'debt + costs'}}</span><span><i class="total-key"></i>{{nl?'reserveringsmodel: totale bezette ruimte':'reservation model: total occupied capacity'}}</span><span><i class="reserve-key"></i>{{nl?'geblokkeerd eigen geld — geen schuld':'blocked own funds — not debt'}}</span><span><i class="debt-key"></i>{{nl?'gereserveerd krediet / schuld + kosten':'reserved credit / debt + costs'}}</span></div><p class="chart-note">{{nl?'Een lage lijn kan ook door weigering ontstaan. In de standaardgegevens weigert CCDII de laptop omdat het volledige bedrag als krediet moet passen; het reserveringsmodel accepteert haar met een combinatie van eigen geld en krediet. Na de melding blijven beide delen tijdelijk bezet en op de ingevoerde oplossingsdatum worden zij weer vrijgegeven.':'A low line may also result from rejection. In the default data, CCDII rejects the laptop because the full amount must fit as credit; the reservation model accepts it using a combination of own funds and credit. After the report, both portions remain occupied temporarily and are released again on the entered resolution date.'}}</p></div>
   <p class="mechanism"><strong>{{nl?'Veilige toestandsovergang:':'Safe state transition:'}}</strong> {{nl?'CONTROLEREN → RESERVEREN → VASTLEGGEN. Bij levering: RESERVEREN → LEVEREN → AFREKENEN.':'CHECK → RESERVE → COMMIT. On delivery: RESERVE → DELIVER → SETTLE.'}}</p>
  </section>
  <section v-if="props.mode!=='transaction'" class="model-section governance">
   <div class="section-head"><b>2</b><div><h4>{{nl?'Moraliteit en governance door de tijd':'Morality and governance over time'}}</h4><p>{{nl?'Onderzoek of winst en managementbeloning vroeg ontstaan terwijl schade, herstel en persoonlijke aanspreekbaarheid later of elders landen.':'Explore whether profit and management rewards arrive early while harm, repair and personal accountability land later or elsewhere.'}}</p></div></div>
   <div class="governance-grid">
    <div class="controls">
     <label :class="{active:activeGovernance==='annualProfit'}" @pointerdown="activeGovernance='annualProfit'" @focusin="activeGovernance='annualProfit'"><span>{{nl?'Jaarwinst':'Annual profit'}} <output>{{money(governance.annualProfit)}} mln</output></span><input v-model.number="governance.annualProfit" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='externalHarm'}" @pointerdown="activeGovernance='externalHarm'" @focusin="activeGovernance='externalHarm'"><span>{{nl?'Schade als het misgaat':'Harm if it occurs'}} <output>{{money(governance.externalHarm)}} mln</output></span><input v-model.number="governance.externalHarm" type="range" min="0" max="200" step="5"></label>
     <label :class="{active:activeGovernance==='baseHarmChance'}" @pointerdown="activeGovernance='baseHarmChance'" @focusin="activeGovernance='baseHarmChance'"><span>{{nl?'Basiskans op langetermijnschade':'Baseline chance of long-term harm'}} <output>{{governance.baseHarmChance}}%</output></span><input v-model.number="governance.baseHarmChance" type="range" min="1" max="90"></label>
     <label :class="{active:activeGovernance==='bonus'}" @pointerdown="activeGovernance='bonus'" @focusin="activeGovernance='bonus'"><span>{{nl?'Directe bonusdruk':'Immediate bonus pressure'}} <output>{{governance.bonus}}%</output></span><input v-model.number="governance.bonus" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='longTermPay'}" @pointerdown="activeGovernance='longTermPay'" @focusin="activeGovernance='longTermPay'"><span>{{nl?'Uitgestelde beloning':'Deferred compensation'}} <output>{{governance.longTermPay}}%</output></span><input v-model.number="governance.longTermPay" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='clawback'}" @pointerdown="activeGovernance='clawback'" @focusin="activeGovernance='clawback'"><span>Clawback <output>{{governance.clawback}}%</output></span><input v-model.number="governance.clawback" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='annualPay'}" @pointerdown="activeGovernance='annualPay'" @focusin="activeGovernance='annualPay'"><span>{{nl?'Jaarbeloning beslisser':'Decision-maker annual compensation'}} <output>{{moneyPrecise(governance.annualPay)}} mln</output></span><input v-model.number="governance.annualPay" type="range" min="0.1" max="5" step="0.1"></label>
     <label :class="{active:activeGovernance==='stakeYears'}" @pointerdown="activeGovernance='stakeYears'" @focusin="activeGovernance='stakeYears'"><span>{{nl?'Persoonlijk bedrag op het spel':'Personal amount at risk'}} <output>{{governance.stakeYears}}× {{nl?'jaarbeloning':'annual pay'}}</output></span><input v-model.number="governance.stakeYears" type="range" min="0" max="5" step="0.5"></label>
     <label :class="{active:activeGovernance==='detection'}" @pointerdown="activeGovernance='detection'" @focusin="activeGovernance='detection'"><span>{{nl?'Onafhankelijke ontdekking':'Independent detection'}} <output>{{governance.detection}}%</output></span><input v-model.number="governance.detection" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='attribution'}" @pointerdown="activeGovernance='attribution'" @focusin="activeGovernance='attribution'"><span>{{nl?'Toeschrijving aan beslissers':'Attribution to decision-makers'}} <output>{{governance.attribution}}%</output></span><input v-model.number="governance.attribution" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='enforcement'}" @pointerdown="activeGovernance='enforcement'" @focusin="activeGovernance='enforcement'"><span>{{nl?'Daadwerkelijke handhaving':'Actual enforcement'}} <output>{{governance.enforcement}}%</output></span><input v-model.number="governance.enforcement" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='culpability'}" @pointerdown="activeGovernance='culpability'" @focusin="activeGovernance='culpability'"><span>{{nl?'Verwijtbaarheid':'Culpability'}} <output>{{culpabilityLabel}}</output></span><input v-model.number="governance.culpability" type="range" min="0" max="3" step="1"></label>
     <label :class="{active:activeGovernance==='reportProtection'}" @pointerdown="activeGovernance='reportProtection'" @focusin="activeGovernance='reportProtection'"><span>{{nl?'Ruimte en bescherming om te melden':'Scope and protection to report'}} <output>{{governance.reportProtection}}%</output></span><input v-model.number="governance.reportProtection" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='provision'}" @pointerdown="activeGovernance='provision'" @focusin="activeGovernance='provision'"><span>{{nl?'Voorziening voor schade':'Provision for harm'}} <output>{{governance.provision}}%</output></span><input v-model.number="governance.provision" type="range" min="0" max="100"></label>
     <label :class="{active:activeGovernance==='horizon'}" @pointerdown="activeGovernance='horizon'" @focusin="activeGovernance='horizon'"><span>{{nl?'Moment waarop gevolgen blijken':'When consequences emerge'}} <output>{{governance.horizon}} {{nl?'jaar':'years'}}</output></span><input v-model.number="governance.horizon" type="range" min="1" max="15"></label>
    </div>
    <div class="governance-result">
     <div class="risk-chain">
      <article><span>{{nl?'KANS OP SCHADE':'CHANCE OF HARM'}}</span><b>{{pct(governanceRisk.harmChance)}}%</b><small>{{pct(governanceRisk.harmChanceHigh)}}–{{pct(governanceRisk.harmChanceLow)}}% {{nl?'bij sterke tot zwakke gedragsreactie':'under strong to weak behavioural response'}}</small></article><i>→</i>
      <article><span>{{nl?'ONGEMELD':'UNREPORTED'}}</span><b>{{pct(governanceRisk.unreported)}}%</b><small>{{nl?'kans dat ontstane schade intern noch extern bovenkomt':'chance that harm which occurs emerges neither internally nor externally'}}</small></article><i>→</i>
      <article><span>{{nl?'AANSPREEKBAAR':'HELD ACCOUNTABLE'}}</span><b>{{pct(governanceRisk.accountability)}}%</b><small>{{nl?'kans op persoonlijke consequenties als schade ontstaat':'chance of personal consequences if harm occurs'}}</small></article>
     </div>
     <div class="governance-metrics">
      <article><span>{{nl?'Verwachte schade':'Expected harm'}}</span><b>{{money(governanceRisk.expectedHarm)}} mln</b><small>{{money(governance.externalHarm)}} × {{pct(governanceRisk.harmChance)}}%</small></article>
      <article><span>{{nl?'Vooraf gedekt':'Covered in advance'}}</span><b>{{money(governanceRisk.coveredHarm)}} mln</b><small>{{governance.provision}}% {{nl?'van de verwachte schade':'of expected harm'}}</small></article>
      <article class="gap"><span>{{nl?'Verwacht ongedekt':'Expected uncovered'}}</span><b>{{money(governanceRisk.uncoveredHarm)}} mln</b><small>{{nl?'komt mogelijk bij anderen of de toekomst terecht':'may fall on others or the future'}}</small></article>
      <article><span>{{nl?'Maximaal persoonlijk bedrag':'Maximum personal amount'}}</span><b>{{moneyPrecise(governanceRisk.amountAtRisk)}} mln</b><small>{{nl?'jaarbeloning plus terugvorderbare uitgestelde beloning':'annual pay plus recoverable deferred compensation'}}</small></article>
      <article><span>{{nl?'Verwachte persoonlijke consequentie':'Expected personal consequence'}}</span><b>{{moneyPrecise(governanceRisk.personalExposure)}} mln</b><small>{{nl?'kans op aanspreekbaarheid × maximaal bedrag':'probability of accountability × maximum amount'}}</small></article>
     </div>
     <div class="score"><span>{{nl?'Afstemming over tijd':'Alignment over time'}}</span><div><i :style="{width:`${pct(governanceRisk.alignment)}%`}"></i></div><b>{{pct(governanceRisk.alignment)}}%</b></div>
     <p>{{nl?'Directe beloningsprikkel':'Immediate reward incentive'}}: <b>{{money(shortReward)}} mln</b> · {{nl?'uitgestelde beloning':'deferred reward'}}: <b>{{money(delayedReward)}} mln</b>. {{nl?'De score vat preventie, zichtbaarheid, aanspreekbaarheid en dekking samen. De afzonderlijke kansen erboven zijn inhoudelijk belangrijker dan dit ene samenvattende getal.':'The score combines prevention, visibility, accountability and coverage. The separate probabilities above are more informative than this single summary number.'}}</p>
     <aside class="governance-help"><span>{{nl?'DEZE INSTELLING':'THIS CONTROL'}}</span><strong>{{governanceHelp.title}}</strong><p>{{governanceHelp.text}}</p></aside>
     <details class="governance-assumptions"><summary>{{nl?'Aannames en rekenrelaties':'Assumptions and calculation relationships'}}</summary><p>{{nl?'Dit is een gevoeligheidsmodel, geen empirisch gekalibreerde voorspeller. Aanspreekbaarheid ontstaat alleen als schade intern of onafhankelijk wordt ontdekt, aan beslissers kan worden toegeschreven, daadwerkelijk wordt gehandhaafd én voldoende verwijtbaar is. Het verwachte persoonlijke gevolg is die samengestelde kans maal het concrete maximumbedrag dat op het spel staat.':'This is a sensitivity model, not an empirically calibrated predictor. Accountability arises only when harm is reported internally or detected independently, can be attributed to decision-makers, is actually enforced and is sufficiently culpable. The expected personal consequence is that combined probability multiplied by the concrete maximum amount at risk.'}}</p><p>{{nl?'Hoe sterk die verwachte consequentie gedrag vooraf verandert, is onzeker. Daarom toont het model geen enkel exact preventiecijfer maar een bandbreedte voor een zwakke, gemiddelde en sterke gedragsreactie. Een gewone zakelijke tegenvaller levert in dit model geen persoonlijke sanctie op. Een langere tijdshorizon verlaagt ontdekking en toeschrijving; een schadevoorziening dekt gevolgen maar voorkomt de schade zelf niet. De waarden moeten voor werkelijk gebruik per sector met gegevens worden gekalibreerd.':'How strongly that expected consequence changes behaviour in advance is uncertain. The model therefore shows a range for weak, medium and strong behavioural responses rather than one exact preventive effect. An ordinary adverse business outcome produces no personal sanction in this model. A longer time horizon reduces detection and attribution; a provision covers consequences but does not prevent harm itself. The values require sector-specific calibration before real-world use.'}}</p></details>
    </div>
   </div>
  </section>
  <footer>{{nl?'Wijzig één aanname tegelijk. Alle uitkomsten zijn illustratieve indices, geen gemeten kansen, kredietadvies of juridische beoordeling.':'Change one assumption at a time. All outcomes are illustrative indices, not measured probabilities, credit advice or legal assessments.'}}</footer>
